style.ifMode:
p.radio > * {
    display: inline;
    float: none !important;
    min-width: initial;
}

form fieldset {
    min-width: 90%;
    display: block;
}

form input[type="radio"], .form input[type="radio"] {
    float: none;
    display: inline-block;
}

form label, .form label {
    display: inline-block;
}

.boxed {
    background: #F2F2F2;
    box-shadow: 3px 3px 3px 1px rgba(0, 0, 0, 0.2);
    padding: 10px 5px 10px 15px;
}

.dateDatepickerInTheFuture label{
    display: block;
}

#initial_allergies .label{
  display:none;
 }

.confirm-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0,0,0,0.45);
    display: none;
    z-index: 9999;
}

.confirm-box {
    width: 340px;
    max-width: 90%;
    background: #fff;
    padding: 20px;
    border-radius: 8px;
    margin: 200px auto;
    position: relative;
    box-shadow: 0 12px 30px rgba(0,0,0,0.3);
    animation: popIn 0.15s ease-out;
}

.confirm-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
}

.btn {
    padding: 8px 16px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn.cancel {
    background: #dc3545 !important;
}

.btn.ok {
    background: #fd7e14 !important;
    color: #fff;
}

@keyframes popIn {
    from { transform: scale(0.95); opacity: 0; }
    to { transform: scale(1); opacity: 1; }
}

excludeIf.script:
  const yesConceptId = '';
  const noConceptId = '';
  const unknownConceptId = '';

  const treatmentLineFirst = '';
  const treatmentLineSecond = '';
  const treatmentLineThird = '';

  const prophylaxisIsoniazidTreatmentLinePrimary = '';
  const prophylaxisIsoniazidTreatmentLineSecondary = '';
  const prophylaxisIsoniazidMedication = '';
  const prophylaxisIsoniazidPrimary = '';
  const prophylaxisIsoniazidSecondary= '';


  const REGIMEN_AZT_3TC_EFV_ID = '';
  const REGIMEN_AZT_3TC_NVP_ID = '';
  const REGIMEN_AZT_3TC_ATV_R_ID = '';
  const REGIMEN_AZT_3TC_LPV_R_ID = '';
  const REGIMEN_TDF_3TC_DTG_ID = '';
  const REGIMEN_TDF_3TC_EFV_ID = '';
  const REGIMEN_TDF_3TC_NVP_ID = '';
  const REGIMEN_TDF_3TC_ATV_R_ID = '';
  const REGIMEN_TDF_3TC_LPV_R_ID = '';
  const REGIMEN_OTHER_ID = '';

  jq(document).ready(function() {


  let previousArvDate = null;
  let PreviousTreatmentLineValue=null
  var regimenUuid='3cd9491e-26fe-102b-80cb-0017a47871b2'

  prophylaxisMedicationNameUuid='3ce29244-26fe-102b-80cb-0017a47871b2'
  prophylaxisTreatmentLineUuid='4dfefa8d-9940-4ad5-800d-f16579b37d54'

  prophylaxisStartDateUuid='163526AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA'
  prophylaxisStopDateUuid='164384AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA'

  InitialprophylaxisStartDateUuid='3cd7cecc-26fe-102b-80cb-0017a47871b2'
  InitialprophylaxisStopDateUuid='3cd7d05c-26fe-102b-80cb-0017a47871b2'

  var medicationSideEffectUuid='164377AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA';
  var artTreatmentLineUuid='0c709500-0cf8-4959-b244-3e9d24dcacc0';
  var artStartDateUuid='159599AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA';
  var medicationSideEffectCodedUuid='165273AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA';
  const contextPath = window.location.href.split('/')[3];
  const apiBaseUrl = "/" + contextPath + "/ws/rest/v1";
  const chwNameConceptUuid = "164141AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA";
  const patientUuid = '';

  let currentEncounterDate = new Date();
  let encounterDate = '';
  if (typeof encounterDate !== "undefined" && encounterDate !== null && (encounterDate.length > 0)) {
      currentEncounterDate = new Date(+encounterDate);
  }

  let lastRecordedChw = {
      name: "",
      date: null,
      encounterDisplay: ""
  };

  jq.getJSON(apiBaseUrl + "/obs", {
      concept: chwNameConceptUuid,
      patient: patientUuid,
      v:
      'custom:(uuid,display,obsDatetime,value,encounter:(display,encounterDatetime,location:(display),encounterType:(display)))'
  },
  function( data ){
      if (data.results.length > 0) {
          for (let index = 0; index < data.results.length; ++index) {
              let chwObs = data.results[index];
              let chwObsDate = new Date(chwObs.obsDatetime);
              let tmpChwObs = {
                  name: "",
                  date: null,
                  encounterDisplay: ""
              };
              if( (currentEncounterDate.getTime() >= chwObsDate.getTime()) ||
                  (currentEncounterDate.toDateString() === chwObsDate.toDateString())) {
                  if (typeof chwObs.value !== "undefined" && chwObs.value !== null && (chwObs.value.length > 0)) {
                      tmpChwObs.name = chwObs.value;
                      tmpChwObs.date = chwObsDate;
                      tmpChwObs.encounterDisplay = chwObs.encounter.display;
                  }
              }
              if ( (tmpChwObs.date != null) &&
                  ((lastRecordedChw.date == null) || (lastRecordedChw.date.getTime() < tmpChwObs.date.getTime()) ) ) {

                  lastRecordedChw.name = tmpChwObs.name;
                  lastRecordedChw.date = tmpChwObs.date;
                  lastRecordedChw.encounterDisplay = tmpChwObs.encounterDisplay;
              }
          }
      }
      if (lastRecordedChw.date != null) {
          jq("#lastRecordedCHW").text(lastRecordedChw.name);
          jq("#lastRecordedCHWEncounter").text(lastRecordedChw.encounterDisplay);
          jq("#lastRecorded-CHW-div").show();
      } else {
          //show the div with the normal obs behaviour
          jq("#normal-CHW-div").show();
      }
  });

  jq("#changeChw").on('change', function(){
      if (this.checked === true) {
          jq("#editChwNameDiv").show();
      } else {
          jq("#editChwNameDiv").hide();
      }
  });

  jq('#takingARVs input[type="radio"]').on('change', function () {
      const selectedValue = $(this).val();
          if(selectedValue == 1 || selectedValue == 2){
              getArtTreatmentLine(apiBaseUrl,artTreatmentLineUuid,patientUuid);
              getArtStartDate(apiBaseUrl,artStartDateUuid,patientUuid)
           }
  });

  getArtTreatmentLine(apiBaseUrl,artTreatmentLineUuid,patientUuid);
  getArtStartDate(apiBaseUrl,artStartDateUuid,patientUuid)
  getRegiment(apiBaseUrl,regimenUuid,patientUuid)

  getProphylaxisIsoniazideMedicationNameUuid(apiBaseUrl,prophylaxisMedicationNameUuid,patientUuid)
  getProphylaxisIsoniazideTreatmentLineUuid(apiBaseUrl, prophylaxisTreatmentLineUuid,patientUuid);

  getProphylaxisIsoniazideStartDateUuid(apiBaseUrl, prophylaxisStartDateUuid,InitialprophylaxisStartDateUuid, patientUuid)
  getProphylaxisIsoniazideStopDateUuid(apiBaseUrl, prophylaxisStopDateUuid,InitialprophylaxisStopDateUuid, patientUuid)


       jq('#treatmentLine input[type="radio"]').on('change',function() {

          const previousValue = localStorage.getItem('previousTreatmentLineValue');

           if (!previousValue) return;
              const selectedValue =getStringValue( jq(this).val());
             setTreatmentLine(selectedValue)
              const message = formatMessage( i18n.confirmChange, [previousValue, selectedValue] );
              showConfirmBox( message,
              ()=> setTreatmentLine(selectedValue) ,
              ()=> setTreatmentLine(previousValue)
              );

        });

  jq('#currentARV1 select').on('change',function() {
  getRegiment(apiBaseUrl,regimenUuid,patientUuid)
          showConfirmBox( i18n.confirmRegimen,
            ()=> {}  ,
            ()=> getRegiment(apiBaseUrl,regimenUuid,patientUuid)
           );
     });
  });


  function getArtTreatmentLine(apiBaseUrl,artTreatmentLineUuid,patientUuid){
      jq.getJSON(apiBaseUrl + "/obs", {
          concept: artTreatmentLineUuid,
          patient: patientUuid,
          v: "custom:(auditInfo:(dateCreated),value:(name:(display)),encounter:(encounterDatetime))"
          }, function (data) {
      if (data.results.length > 0) {
      const res = [...data.results].sort((a, b) =>new Date(a.encounter.encounterDatetime) - new Date(b.encounter.encounterDatetime) );

       var response =(res.length > 1)? res[res.length -1].value.name.display : res[0].value.name.display

        localStorage.setItem('previousTreatmentLineValue', response);
         setTreatmentLine(response)
      }
  });

  }

  function getArtStartDate(apiBaseUrl,artStartDateUuid,patientUuid){
      jq.getJSON(apiBaseUrl + "/obs", {
              concept: artStartDateUuid,
              patient: patientUuid,
              v: "custom:(auditInfo:(dateCreated),value:(name:(display)),encounter:(encounterDatetime))"
          }, function (data) {
          if (data.results.length > 0) {

             const res = [...data.results].sort((a, b) =>new Date(a.encounter.encounterDatetime) - new Date(b.encounter.encounterDatetime) );
              previousArvDate=(res.length > 1)? formatEncounterDate(res[res.length -1]) :formatEncounterDate(res[0])
              getField("arv_start_date.value").datepicker("setDate", previousArvDate)
          }
      });

  }

  function getRegiment(apiBaseUrl,regimenUuid,patientUuid){
      jq.getJSON(apiBaseUrl + "/obs", {
          concept: regimenUuid,
          patient: patientUuid,
          v: "custom:(auditInfo:(dateCreated),value:(name:(display)),encounter:(encounterDatetime))"

      }, function (data) {
      if (data.results.length > 0) {

          const res = [...data.results].sort((a, b) =>new Date(a.encounter.encounterDatetime) - new Date(b.encounter.encounterDatetime) );
           var response =(res.length > 1)? res[res.length -1].value.name.display : res[0].value.name.display

           setCurrentARV(response)
          console.log("Regime: ",response)
      }
  });

}

  function formatEncounterDate(dateFromServer){
     const parts = dateFromServer.value.split("-");
      return new Date( parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10) );
  }
  function getLatestDrugAllergies(apiBaseUrl,medicationSideEffectUuid,patientUuid ){
           jq.getJSON(apiBaseUrl + "/obs", {
               concept: medicationSideEffectUuid,
               patient: patientUuid,
               v:'custom:(auditInfo:(dateCreated),encounter:(encounterDatetime),value)',
           },
            function( data ){
              if (data.results.length > 0) {
               const latestObs = [...data.results].sort((a, b) =>new Date(b.encounter.encounterDatetime) - new Date(a.encounter.encounterDatetime) );
               const oldestObs = [...data.results].sort((a, b) =>new Date(a.encounter.encounterDatetime) - new Date(b.encounter.encounterDatetime) )[0];

               if(latestObs.length > 1){
                  jq("#drug_allergy_specify_value input[type='text']").val(latestObs[0].value)
                }
               if(oldestObs.value){
                 jq("#initial_allergies .label").show()
                 jq("#initial_allergies .value").text(oldestObs.value);
                 }

           } else {
            console.log("Null Value");
            }
         });

  }

  function getLatestSideEffectMedicationCoded(apiBaseUrl,medicationSideEffectCodedUuid,patientUuid ){
      jq.getJSON(apiBaseUrl + "/obs", {
              concept: medicationSideEffectCodedUuid,
              patient: patientUuid,
              v:'custom:(auditInfo:(dateCreated),value:(name)',
      },
      function( data ){
        if (data.results.length > 0) {
          const latestObs = data.results .sort((a, b) => new Date(b.auditInfo.dateCreated) - new Date(a.auditInfo.dateCreated))[0];
           setAlreadySelectedDrugAllergyOption(latestObs.value.name.display)
       } else {

        }
       });
  }

  function getProphylaxisDate(apiBaseUrl, conceptUuid, patientUuid) {
      return new Promise((resolve) => {
          jq.getJSON(apiBaseUrl + "/obs", {
          concept: conceptUuid,
          patient: patientUuid,
          v: 'full',
      }, function (data) {

  if (!data.results || data.results.length === 0) {
      console.log("No prophylaxis treatment line found");
      resolve(null);
      return;
  }

  const latestObs = data.results[0];

  if (!latestObs.value) {
      console.log("No date value found");
      resolve(null);
      return;
  }

  const [year, month, day] = latestObs.value.split("-").map(Number);
  const date = new Date(year, month - 1, day);

  resolve(date);
   });
  });
  }



  function getProphylaxisIsoniazideMedicationNameUuid(apiBaseUrl, prophylaxisMedicationNameUuid,patientUuid) {
          jq.getJSON(apiBaseUrl + "/obs", {
          concept: prophylaxisMedicationNameUuid,
          patient: patientUuid,
          v: 'full',
        }, function (data) {

      if (!data.results || data.results.length === 0) {
          console.log("No prophylaxis treatment found");
          return;
      }
  const latestObs = [...data.results].sort((a, b) =>new Date(a.encounter.encounterDatetime) - new Date(b.encounter.encounterDatetime) );
  var response =(latestObs.length > 1)? latestObs[latestObs.length -1]: latestObs[0]

      const map = {
          "Isoniazide": prophylaxisIsoniazidMedication,
          "Isoniazid": prophylaxisIsoniazidMedication
      };
     const drug = response.value.display;
      const checkboxValue = map[drug];
      if (!checkboxValue) return;
      const checkbox = jq('#Isoniazide input[type="checkbox"][value="' + checkboxValue + '"]');
      if (!checkbox.prop('checked')) {
          checkbox.prop('checked', true);
          checkbox.trigger('change');
      }
    });
  }

  function getProphylaxisIsoniazideTreatmentLineUuid(apiBaseUrl, prophylaxisTreatmentLineUuid,patientUuid) {
          jq.getJSON(apiBaseUrl + "/obs", {
          concept: prophylaxisTreatmentLineUuid,
          patient: patientUuid,
          v: 'full',
        }, function (data) {

      if (!data.results || data.results.length === 0) {
          console.log("No prophylaxis treatment line found");
          return;
      }
  const latestObs = [...data.results].sort((a, b) =>new Date(a.encounter.encounterDatetime) - new Date(b.encounter.encounterDatetime) );
  var response =(latestObs.length > 1)? latestObs[latestObs.length -1]: latestObs[0]

  const type = response.value.display;
  const typeMap = {
      "Primary": prophylaxisIsoniazidPrimary,
      "Primaire": prophylaxisIsoniazidPrimary,
      "Secondary": prophylaxisIsoniazidSecondary,
      "Secondaire": prophylaxisIsoniazidSecondary
     };

      if(type){
          const radioValue = typeMap[type];
          if (radioValue) {

              jq('#Isoniazide input[type="checkbox"]')
                  .prop('checked', true)
                  .trigger('change');
                   const inhStartDate = jq('#inhStartDate');

              jq('#prophylaxis_treatmentLine input[type="radio"][value="' + radioValue + '"]')
                  .prop('checked', true)
                  .trigger('change')
                  .trigger('click');

                   inhStartDate.find('.field-error').hide();
                   inhStartDate.find('input').removeAttr('required');

          }

  } else {
          console.log("Treatment line value does not match expected options: ", type);
  }


    });
  }

  async  function getProphylaxisIsoniazideStartDateUuid(apiBaseUrl, prophylaxisStartDateUuid,InitialprophylaxisStartDateUuid, patientUuid) {
  const [initialStartDate, prophylaxisStartDate] = await Promise.all([
      getProphylaxisDate(apiBaseUrl, InitialprophylaxisStartDateUuid, patientUuid),
      getProphylaxisDate(apiBaseUrl, prophylaxisStartDateUuid, patientUuid)
  ]);
  const startDate = (initialStartDate && !prophylaxisStartDate) ? initialStartDate : prophylaxisStartDate;
  getField("inhStartDate.value").datepicker("setDate", startDate || null);
  }

   async function getProphylaxisIsoniazideStopDateUuid(apiBaseUrl, prophylaxisStopDateUuid,InitialprophylaxisStopDateUuid, patientUuid) {
      const [initialStopDate, prophylaxisStopDate] = await Promise.all([
        getProphylaxisDate(apiBaseUrl, InitialprophylaxisStopDateUuid, patientUuid),
       getProphylaxisDate(apiBaseUrl, prophylaxisStopDateUuid, patientUuid)
       ]);
   const endDate = (initialStopDate && !prophylaxisStopDate) ? initialStopDate : prophylaxisStopDate;
   getField("inhEndDate.value").datepicker("setDate", endDate || null);
}

  function setAlreadySelectedDrugAllergyOption(option){
     const mapValue =
       {
        yes: yesConceptId,
        no: noConceptId,
        unknown: unknownConceptId
       }
    const radioValue = mapValue[option.toLowerCase().trim()];
    if (radioValue) {
         $('#drug_allergy_question input[type="radio"][value="' + radioValue + '"]')
            .prop('checked', true)
            .trigger('change');
        }
  }

  function getStringValue(conceptId) {
  const map = {
      [treatmentLineFirst]:  "1st",
      [treatmentLineSecond]: "2nd",
      [treatmentLineThird]:  "3rd",
      [treatmentLineFirst]:  "1ère",
      [treatmentLineSecond]: "2ème",
      [treatmentLineThird]:  "3ème",

  };
    return map[conceptId] || conceptId;
  }

  function setTreatmentLine(serverValue) {
  const map = {
      "1ère":  [treatmentLineFirst],
      "2ème":  [treatmentLineSecond],
      "3ème":  [treatmentLineThird],
      "1st":   [treatmentLineFirst],
      "2nd":   [treatmentLineSecond],
      "3rd":   [treatmentLineThird]
  };
  const radioValue = map[serverValue];
      if (!radioValue) return;
      jq('#treatmentLine input[type="radio"][value="' + radioValue + '"]')
      .prop('checked', true)
      .trigger('click');
  }

  function setCurrentARV(serverValue) {
      const map = {
          "AZT + 3TC + EFV": [REGIMEN_AZT_3TC_EFV_ID],
          "AZT + 3TC + NVP": [REGIMEN_AZT_3TC_NVP_ID],
          "AZT + 3TC + ATV/r": [REGIMEN_AZT_3TC_ATV_R_ID],
          "AZT + 3TC + LPR/r": [REGIMEN_AZT_3TC_LPV_R_ID],
          "TDF + 3TC + DTG": [REGIMEN_TDF_3TC_DTG_ID],
          "TDF + 3TC + EFV": [REGIMEN_TDF_3TC_EFV_ID],
          "TDF + 3TC + NVP": [REGIMEN_TDF_3TC_NVP_ID],
          "TDF + 3TC + ATV/r": [REGIMEN_TDF_3TC_ATV_R_ID],
          "TDF + 3TC + LPV/r": [REGIMEN_TDF_3TC_LPV_R_ID],
          "Other": [REGIMEN_OTHER_ID]
      };

      const optionValue = map[serverValue];
      if (!optionValue) return;
      localStorage.setItem('previousARVValue', optionValue);
      jq('#currentARV1 select').val(optionValue);
  }

ifMode.script:
jq(function() {
    setUpDatepickerStartAndEndDateValidation();
    setUpObsWithObsDateTime('syph-checkbox');

    manageInputActivationForRadioButton("#Isoniazide","#prophylaxis_treatmentLine",["#inhStartDate","#inhEndDate"],'');

    // handlers for next and submit buttons, see nextAndSubmitButtons.js
    setUpNextAndSubmitButtons();
});

includeIf.script:
jq(function() {
    var encounterDate = '';
    setUpEdd(encounterDate,'');
    validateEstimatedDeliveryDate("edd", new Date(+encounterDate), '');
    eddCannotBeOlderThanTwoWeeks("edd", new Date(+encounterDate), '');
});

htmlform.script:
jq(document).ready(function() {
// Only show the TB screening result question if it has been answered. Only collected historically
var showTbScreening = (typeof getValue !== 'undefined' && getValue('tbScreeningResultQuestion.value'));
// Edit mode
showTbScreening = showTbScreening || (typeof getValue === 'undefined' &&
jq('.tb-screening-result-section').find('.value').length > 0); // View mode
if (showTbScreening) {
jq('.tb-screening-result-section').show();
}
else {
jq('.tb-screening-result-section').hide();
}
});
